using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;using MYOB.Data;using MYOB.DTOs;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Operations.CustomerDeliveries;public class CreateModel(ApplicationDbContext db,ITransactionService transactions,IPermissionService permissions):PageModel
{[BindProperty]public CustomerDeliveryForm Item{get;set;}=new();public SelectList Customers{get;private set;}=null!;public IReadOnlyList<PolicyOption> Policies{get;private set;}=[];public async Task<IActionResult> OnGetAsync(Guid? policyId){if(!await permissions.HasAsync(User,ScreenCatalog.CustomerDeliveries,PermissionAction.Add))return Forbid();await Load();if(policyId.HasValue){if(!Policies.Any(x=>x.Id==policyId.Value))return BadRequest("البوليصة غير متاحة للتوريد. يرجى تحديث لوحة الأعمال.");Item.SupplierReceiptId=policyId.Value;}return Page();}public async Task<IActionResult> OnPostAsync(){if(!await permissions.HasAsync(User,ScreenCatalog.CustomerDeliveries,PermissionAction.Add))return Forbid();if(ModelState.IsValid)try{await transactions.CreateCustomerDeliveryAsync(new(Item.CustomerId,Item.SupplierReceiptId,Item.Date,Item.UnitPrice,Item.TaxPercent,Item.Details));TempData["Message"]="تم تسجيل توريد البضاعة";return RedirectToPage("Index");}catch(InvalidOperationException e){ModelState.AddModelError(string.Empty,e.Message);}await Load();return Page();}private async Task Load(){Customers=new(await db.Customers.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(),"Id","Name");Policies=await transactions.GetUnassignedPoliciesAsync();}}
